/*
 * EXTRACTED COPY for review convenience only.
 * Source of truth: the single <script> block at the bottom of index.html.
 * Generated from index.html; do not edit this file independently.
 */

(() => {
  'use strict';

  const mainNav = document.getElementById('mainNav');
  const heroSection = document.getElementById('heroSection');
  const navList = document.querySelector('.nav-links');
  const hamburger = document.querySelector('.hamburger');
  const logo = document.querySelector('.nav-logo');
  const tabSections = Array.from(document.querySelectorAll('section.tab-content'));
  const tabById = new Map(tabSections.map(section => [section.id, section]));
  const navAnchors = Array.from(document.querySelectorAll('.nav-links a[href^="#"]'));
  const tabAnchors = Array.from(document.querySelectorAll('.nav-links a[href^="#"], .hero-nav-btn[href^="#"]'));

  function isPlainPrimaryClick(event) {
    return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey;
  }

  function setMobileMenuOpen(open) {
    if (!navList || !hamburger) return;
    const isOpen = Boolean(open);
    navList.classList.toggle('is-open', isOpen);
    hamburger.setAttribute('aria-expanded', String(isOpen));
    hamburger.setAttribute('aria-label', isOpen ? 'Close navigation' : 'Open navigation');
    hamburger.textContent = isOpen ? '×' : '☰';
  }

  function closeMobileMenu() {
    setMobileMenuOpen(false);
  }

  setMobileMenuOpen(false);

  if (mainNav) {
    const updateNavState = () => {
      mainNav.classList.toggle('scrolled', window.scrollY > 50);
    };
    window.addEventListener('scroll', updateNavState, { passive: true });
    updateNavState();
  }

  if (hamburger) {
    hamburger.addEventListener('click', () => {
      const isOpen = hamburger.getAttribute('aria-expanded') === 'true';
      setMobileMenuOpen(!isOpen);
    });
  }

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') closeMobileMenu();
  });

  document.addEventListener('click', event => {
    if (mainNav && event.target instanceof Node && !mainNav.contains(event.target)) {
      closeMobileMenu();
    }
  });

  const mobileMedia = window.matchMedia('(max-width: 900px)');
  const handleViewportChange = event => {
    if (!event.matches) closeMobileMenu();
  };
  if (typeof mobileMedia.addEventListener === 'function') {
    mobileMedia.addEventListener('change', handleViewportChange);
  } else if (typeof mobileMedia.addListener === 'function') {
    mobileMedia.addListener(handleViewportChange);
  }

  let lastSyncedHref = '';

  function tabIdFromLocation() {
    if (!window.location.hash) return null;
    try {
      const tabId = decodeURIComponent(window.location.hash.slice(1));
      return tabById.has(tabId) ? tabId : null;
    } catch (error) {
      console.warn('Ignoring malformed URL hash:', error);
      return null;
    }
  }

  function activateView(tabId, options = {}) {
    const {
      historyMode = 'none',
      scrollBehavior = 'smooth',
    } = options;
    const hasTab = typeof tabId === 'string' && tabById.has(tabId);
    const activeId = hasTab ? tabId : null;

    if (heroSection) {
      heroSection.hidden = hasTab;
      heroSection.setAttribute('aria-hidden', String(hasTab));
    }

    tabSections.forEach(section => {
      const isActive = section.id === activeId;
      section.classList.toggle('active', isActive);
      section.setAttribute('aria-hidden', String(!isActive));
    });

    navAnchors.forEach(anchor => {
      const isActive = anchor.getAttribute('href') === `#${activeId}`;
      anchor.classList.toggle('active', isActive);
      if (isActive) {
        anchor.setAttribute('aria-current', 'page');
      } else {
        anchor.removeAttribute('aria-current');
      }
    });

    closeMobileMenu();

    if (historyMode !== 'none') {
      const url = new URL(window.location.href);
      url.hash = activeId || '';
      if (url.href !== window.location.href) {
        const state = { tab: activeId };
        if (historyMode === 'replace') {
          window.history.replaceState(state, '', url);
        } else {
          window.history.pushState(state, '', url);
        }
      }
      lastSyncedHref = window.location.href;
    }

    window.scrollTo({ top: 0, left: 0, behavior: scrollBehavior });
  }

  tabAnchors.forEach(anchor => {
    anchor.addEventListener('click', event => {
      if (!isPlainPrimaryClick(event)) return;
      const href = anchor.getAttribute('href') || '';
      const tabId = href.startsWith('#') ? href.slice(1) : '';
      if (!tabById.has(tabId)) return;
      event.preventDefault();
      activateView(tabId, { historyMode: 'push' });
    });
  });

  if (logo) {
    logo.addEventListener('click', event => {
      if (!isPlainPrimaryClick(event)) return;
      event.preventDefault();
      activateView(null, { historyMode: 'push' });
    });
  }

  function syncViewFromLocation(scrollBehavior = 'auto') {
    if (lastSyncedHref === window.location.href) return;
    lastSyncedHref = window.location.href;
    activateView(tabIdFromLocation(), { historyMode: 'none', scrollBehavior });
  }

  window.addEventListener('popstate', () => syncViewFromLocation('auto'));
  window.addEventListener('hashchange', () => syncViewFromLocation('auto'));
  syncViewFromLocation('auto');

  const citationStatus = document.getElementById('citation-status');
  const citationSections = ['first_author', 'student', 'coauthor'];

  function normalizedCitationCount(value) {
    if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
      return Math.trunc(value);
    }
    if (typeof value === 'string' && /^\d+$/.test(value.trim())) {
      return Number.parseInt(value.trim(), 10);
    }
    return null;
  }

  function cleanTimestamp(value) {
    if (typeof value !== 'string') return '';
    return value.split(' (', 1)[0].trim();
  }

  function setCitationBadge(item, rawCount) {
    let badge = item.querySelector('.cite-badge[data-citation-badge], .cite-badge');
    const count = normalizedCitationCount(rawCount);

    if (count === null || count <= 0) {
      if (badge) badge.remove();
      return false;
    }

    if (!badge) {
      badge = document.createElement('span');
      badge.className = 'cite-badge';
      const links = item.querySelector('.pub-links');
      const info = item.querySelector('.pub-info');
      if (links) {
        links.after(badge);
      } else if (info) {
        info.appendChild(badge);
      } else {
        item.appendChild(badge);
      }
    }

    badge.dataset.citationBadge = '';
    badge.textContent = `${count} ${count === 1 ? 'citation' : 'citations'}`;
    badge.setAttribute('aria-label', `Citation count: ${count}`);
    return true;
  }

  function applyCitations(sectionName, rawMap) {
    const container = document.querySelector(`[data-citation-section="${sectionName}"]`);
    if (!container) {
      console.warn('Citation section not found:', sectionName);
      return 0;
    }

    const citationMap = rawMap && typeof rawMap === 'object' && !Array.isArray(rawMap)
      ? rawMap
      : {};
    let applied = 0;

    container.querySelectorAll(':scope > .pub-item[data-citation-key]').forEach(item => {
      const key = item.dataset.citationKey;
      if (setCitationBadge(item, key ? citationMap[key] : undefined)) applied += 1;
    });

    console.log(`  ${sectionName}: applied ${applied} badges`);
    return applied;
  }

  function renderCitationStatus(data) {
    if (!citationStatus) return;
    const updated = cleanTimestamp(data.updated);
    const lastAttempt = cleanTimestamp(data.last_attempt);
    const isStale = data.status === 'stale';
    const missingCount = Array.isArray(data.missing) ? data.missing.length : 0;

    citationStatus.classList.toggle('is-stale', isStale);
    citationStatus.classList.remove('is-error');

    if (!updated) {
      citationStatus.hidden = true;
      citationStatus.textContent = '';
      return;
    }

    if (isStale) {
      const attemptText = lastAttempt ? ` Refresh attempted ${lastAttempt}.` : '';
      const missingText = missingCount ? ` ${missingCount} record${missingCount === 1 ? '' : 's'} could not be refreshed.` : '';
      citationStatus.textContent = `Citation counts last updated: ${updated}.${attemptText}${missingText} Showing last-known NASA ADS values.`;
    } else {
      citationStatus.textContent = `Citation counts updated: ${updated} via NASA ADS.`;
    }
    citationStatus.hidden = false;
  }

  async function loadCitations() {
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timeoutId = controller
      ? window.setTimeout(() => controller.abort(), 15000)
      : null;

    try {
      const response = await fetch(`citations.json?v=${Date.now()}`, {
        cache: 'no-store',
        headers: { Accept: 'application/json' },
        ...(controller ? { signal: controller.signal } : {}),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const contentType = response.headers.get('content-type') || '';
      if (/text\/html/i.test(contentType)) {
        throw new Error('Expected JSON but received HTML');
      }

      const data = await response.json();
      if (!data || typeof data !== 'object' || Array.isArray(data)) {
        throw new Error('citations.json root must be an object');
      }

      const invalidSections = citationSections.filter(sectionName => {
        const section = data[sectionName];
        return !section || typeof section !== 'object' || Array.isArray(section);
      });
      if (invalidSections.length) {
        throw new Error(`citations.json has invalid or missing sections: ${invalidSections.join(', ')}`);
      }

      console.log('Citations loaded:', cleanTimestamp(data.updated));
      citationSections.forEach(sectionName => {
        applyCitations(sectionName, data[sectionName]);
      });
      renderCitationStatus(data);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn('Citations not loaded:', message);
      if (citationStatus) {
        citationStatus.textContent = 'Citation counts are temporarily unavailable.';
        citationStatus.classList.remove('is-stale');
        citationStatus.classList.add('is-error');
        citationStatus.hidden = false;
      }
    } finally {
      if (timeoutId !== null) window.clearTimeout(timeoutId);
    }
  }

  loadCitations();

  function initializeFadeIn() {
    const elements = document.querySelectorAll(
      '.research-card, .team-card, .pub-item, .highlight-card, .pi-profile, .talk-item'
    );
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (reducedMotion || typeof IntersectionObserver !== 'function') {
      elements.forEach(element => element.classList.add('fade-in', 'is-visible'));
      return;
    }

    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      });
    }, { threshold: 0.1 });

    elements.forEach(element => {
      element.classList.add('fade-in');
      observer.observe(element);
    });
  }

  initializeFadeIn();
})();
